import test from "node:test";
import assert from "node:assert/strict";
import { effectSelections } from "../web/effect-selection.js";

const device = (id, fx) => ({ id, fx, lightingKnown: true, sx: 128 });

test("old heartbeat values cannot undo a queued effect; confirmed and later external changes are displayed", () => {
	const selection = effectSelections();
	const edit = selection.select("peer", 9, [device("local", 0), device("peer", 2)]);
	selection.sent(edit);
	assert.deepEqual(selection.reconcile([device("local", 0), device("peer", 2)]), [device("local", 0), device("peer", 9)]);
	assert.equal(selection.waiting(), true);
	selection.reconcile([device("peer", 9)]);
	assert.equal(selection.waiting(), false);
	assert.equal(selection.reconcile([device("peer", 3)])[0].fx, 3);
});

test("rapid edits survive replies and failures belonging to earlier commands", () => {
	const selection = effectSelections();
	const first = selection.select("peer", 9, [device("peer", 2)]);
	const second = selection.select("peer", 12, [device("peer", 2)]);
	selection.sent(first);
	selection.failed(first);
	assert.equal(selection.reconcile([device("peer", 9)])[0].fx, 12);
	selection.sent(second);
	selection.failed(second);
	assert.equal(selection.reconcile([device("peer", 9)])[0].fx, 9);
});

test("group edits confirm independently, preserve other telemetry and eventually expire", () => {
	let now = 1000;
	const selection = effectSelections(() => now);
	const edit = selection.select("all", 9, [device("one", 0), device("two", 2)]);
	now += 20000; // Waiting in the browser queue does not consume the readback grace period.
	assert.equal(selection.reconcile([device("one", 0), device("two", 2)])[1].fx, 9);
	selection.sent(edit);
	const result = selection.reconcile([device("one", 9), { ...device("two", 2), sx: 77 }]);
	assert.equal(result[1].fx, 9);
	assert.equal(result[1].sx, 77);
	now += 8000;
	assert.equal(selection.reconcile([device("one", 9), device("two", 2)])[1].fx, 2);
	assert.equal(selection.waiting(), false);
});

// Run the real adapter against a queued remote command whose first status still has old telemetry.
test("dashboard refresh after remote command acceptance retains the selected effect", { timeout: 4000 }, async () => {
	const original = Object.fromEntries(["document", "window", "location", "fetch", "setTimeout"].map((key) => [key, globalThis[key]]));
	const controls = new Map(), timers = [], commands = [];
	let command, hydrated, refreshed;
	const ready = new Promise((resolve) => { hydrated = resolve; });
	const updated = new Promise((resolve) => { refreshed = resolve; });
	const status = { ok: true, master: true, settled: true, localId: "local", devices: [
		{ ...device("local", 0), simulated: false, online: true },
		{ ...device("peer", 2), simulated: false, online: true },
	] };
	globalThis.document = {
		hidden: false, addEventListener() {},
		getElementById(id) { if (!controls.has(id)) controls.set(id, { hidden: id === "inlineSettings" }); return controls.get(id); },
	};
	globalThis.window = { addEventListener() {} };
	globalThis.location = { origin: "http://device", hostname: "device", host: "device" };
	globalThis.setTimeout = (handler, delay, ...args) => {
		const timer = original.setTimeout(handler, delay, ...args); timers.push(timer); return timer;
	};
	globalThis.fetch = async (address, options = {}) => {
		if (address === "/json/effects") return Response.json(["Solid", "Blink"]);
		if (address.endsWith("/request")) return Response.json({ id: "a".repeat(32) });
		if (address.includes("/rpc?")) { command = JSON.parse(options.body); commands.push(command); return new Response(null, { status: 202 }); }
		return Response.json(command.op === "lighting" ? { ok: true, accepted: 1 } : status);
	};
	try {
		await import("../web/app.js?effect-selection-test");
		window.glassDeviceBridge.start({
			setEnabled() {}, receivePixels() {}, receiveEffects() {},
			receiveDevices(value) { if (commands.some((item) => item.op === "lighting")) refreshed(value); else hydrated(value); },
		});
		assert.equal((await ready).devices[1].fx, 2);
		window.glassDeviceBridge.change("peer", { effect: 9 }, ["effect"]);
		assert.equal((await updated).devices[1].fx, 9);
		assert.deepEqual(commands.find((item) => item.op === "lighting"), { op: "lighting", target: "peer", body: { independent: true, seg: [{ id: 0, fx: 9 }] } });
		await new Promise((resolve) => original.setTimeout(resolve, 0));
	} finally {
		for (const timer of timers) clearTimeout(timer);
		Object.assign(globalThis, original);
	}
});
